CREATE OR REPLACE FUNCTION private.archive_first_publication()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.status='published' and old.status is distinct from 'published' then
    if not exists(select 1 from public.work_revisions v where v.work_id=new.id and v.status='approved') then
      insert into public.work_revisions(work_id,author_id,status,version_number,snapshot,refs,change_note,reviewed_at)
      values(new.id,new.author_id,'approved',1,private.work_snapshot(new),
        private.references_snapshot(new.id),'初回公開版',now());
    end if;
    if new.current_version=0 then
      update public.works set current_version=1 where id=new.id;
    end if;
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_revision(p_work_id uuid, p_snapshot jsonb, p_references jsonb, p_status text, p_change_note text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_work public.works%rowtype; v_id uuid;
begin
  if (select auth.uid()) is null then raise exception 'ログインしてください'; end if;
  if p_status not in ('draft','pending') then raise exception '不正な改訂状態です'; end if;
  if char_length(coalesce(p_change_note,''))>1000 then raise exception '変更説明が長すぎます'; end if;
  perform private.validate_revision_payload(p_snapshot,p_references);
  select * into v_work from public.works where id=p_work_id for update;
  if not found or v_work.author_id<>(select auth.uid()) or v_work.status<>'published' then
    raise exception 'この作品の改訂は申請できません';
  end if;
  select id into v_id from public.work_revisions
    where work_id=p_work_id and status in ('draft','pending','rejected') for update;
  if v_id is null then
    insert into public.work_revisions(work_id,author_id,status,snapshot,refs,change_note)
    values(p_work_id,(select auth.uid()),p_status,p_snapshot,p_references,coalesce(p_change_note,''))
    returning id into v_id;
  else
    update public.work_revisions set snapshot=p_snapshot,refs=p_references,status=p_status,
      change_note=coalesce(p_change_note,''),review_note='',updated_at=now(),reviewed_at=null
    where id=v_id;
  end if;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.request_publication_action(p_work_id uuid, p_action text, p_reason text DEFAULT ''::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_work public.works%rowtype; v_id uuid;
begin
  if (select auth.uid()) is null then raise exception 'ログインしてください'; end if;
  if p_action not in ('hide','delete') then raise exception '不正な申請です'; end if;
  if char_length(coalesce(p_reason,''))>1000 then raise exception '申請理由が長すぎます'; end if;
  select * into v_work from public.works where id=p_work_id for update;
  if not found or v_work.author_id<>(select auth.uid())
     or (v_work.status<>'published' and not (p_action='delete' and v_work.status='hidden')) then
    raise exception 'この作品について申請できません';
  end if;
  if exists(select 1 from public.publication_requests where work_id=p_work_id and status='pending') then
    raise exception 'すでに対応待ちの申請があります';
  end if;
  insert into public.publication_requests(work_id,author_id,action,reason)
  values(p_work_id,(select auth.uid()),p_action,coalesce(p_reason,'')) returning id into v_id;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.review_publication_request(p_request_id uuid, p_action text, p_review_note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_request public.publication_requests%rowtype; v_work public.works%rowtype;
begin
  if not private.is_moderator() then raise exception '管理者のみ操作できます'; end if;
  if p_action not in ('approve','reject') then raise exception '不正な操作です'; end if;
  if char_length(coalesce(p_review_note,''))>1000 then raise exception '審査コメントが長すぎます'; end if;
  select work_id into v_request.work_id from public.publication_requests where id=p_request_id;
  if v_request.work_id is null then raise exception '申請が見つかりません'; end if;
  select * into v_work from public.works where id=v_request.work_id for update;
  select * into v_request from public.publication_requests where id=p_request_id for update;
  if v_request.status<>'pending' then raise exception '処理待ちではありません'; end if;
  if p_action='reject' then
    update public.publication_requests set status='rejected',review_note=coalesce(p_review_note,''),
      reviewed_at=now() where id=p_request_id;
    return;
  end if;
  if v_request.action='hide' then
    if v_work.status<>'published' then raise exception '現在の作品は公開中ではありません'; end if;
    update public.works set status='hidden' where id=v_work.id;
    update public.publication_requests set status='approved',review_note=coalesce(p_review_note,''),
      reviewed_at=now() where id=p_request_id;
  elsif v_request.action='delete' then
    -- 作品・注釈・改訂履歴・文献・申請は外部キーによりすべて削除。
    delete from public.works where id=v_work.id;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.validate_revision_payload_v781_base(p_data jsonb, p_refs jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_entry jsonb; v_key text;
begin
  if p_data is null or jsonb_typeof(p_data)<>'object' then
    raise exception '改訂本文の形式が正しくありません';
  end if;
  if octet_length(p_data::text)>1000000 then raise exception '作品データが大きすぎます'; end if;
  if exists(select 1 from jsonb_object_keys(p_data) as k(field_name)
            where k.field_name not in ('pen_name','contributor_credit','section','title','genre','theme','summary',
              'body','question','inheritance','novelty')) then
    raise exception '想定外の作品項目が含まれています';
  end if;
  if char_length(btrim(coalesce(p_data->>'pen_name',''))) not between 1 and 80
     or char_length(coalesce(p_data->>'contributor_credit','')) > 120
     or char_length(btrim(coalesce(p_data->>'title',''))) not between 1 and 180
     or char_length(btrim(coalesce(p_data->>'summary',''))) not between 10 and 1000
     or char_length(btrim(coalesce(p_data->>'body',''))) not between 10 and 200000
     or coalesce(p_data->>'genre','') not in ('純文学','実験文学','哲学小説','詩・散文','文芸評論','映画','ノベルゲーム','科学','その他',
        '理論哲学','実践哲学','文芸','アニメ','ゲーム','数学','物理学','脳科学','心理学','精神医学') then
    raise exception '作品名・筆名・本文・紹介または分類を確認してください';
  end if;

  -- 旧版の改訂案には section / contributor_credit が存在しないため、
  -- 大分類がある時だけ整合性をチェックします。
  if p_data ? 'section' then
    if coalesce(p_data->>'section','') not in ('文学','哲学','評論','科学','その他') or not (
      (p_data->>'section'='文学' and p_data->>'genre' in ('純文学','実験文学','詩・散文','哲学小説')) or
      (p_data->>'section'='哲学' and p_data->>'genre' in ('理論哲学','実践哲学')) or
      (p_data->>'section'='評論' and p_data->>'genre' in ('文芸','映画','アニメ','ゲーム','文芸評論','ノベルゲーム')) or
      (p_data->>'section'='科学' and p_data->>'genre' in ('数学','物理学','脳科学','心理学','精神医学','科学')) or
      (p_data->>'section'='その他' and p_data->>'genre'='その他')
    ) then
      raise exception '分野と小分類の組み合わせが正しくありません';
    end if;
  end if;

  -- CASE式とIFのTHENを隣接させず、項目ごとに上限を判定する。
  foreach v_key in array array['theme','question','inheritance','novelty'] loop
    if v_key = 'theme' then
      if char_length(coalesce(p_data->>v_key,'')) > 200 then
        raise exception '作品の補足項目が長すぎます';
      end if;
    else
      if char_length(coalesce(p_data->>v_key,'')) > 2000 then
        raise exception '作品の補足項目が長すぎます';
      end if;
    end if;
  end loop;
  if p_refs is null or jsonb_typeof(p_refs)<>'array' or jsonb_array_length(p_refs)>20 then
    raise exception '参考文献は配列で20件以内にしてください';
  end if;
  if octet_length(p_refs::text)>80000 then raise exception '参考文献データが大きすぎます'; end if;
  for v_entry in select value from jsonb_array_elements(p_refs) loop
    if jsonb_typeof(v_entry)<>'object'
       or char_length(btrim(coalesce(v_entry->>'title',''))) not between 1 and 300
       or char_length(coalesce(v_entry->>'relation',''))>200
       or char_length(coalesce(v_entry->>'url',''))>1000
       or (coalesce(btrim(v_entry->>'url'),'')<>'' and
           btrim(v_entry->>'url') !~ '^https://[^[:space:]]+$') then
      raise exception '参考文献の書名またはURLを確認してください';
    end if;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION private.valid_work_classifications(p_section text, p_genre text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE v_values jsonb;v_value jsonb;v_name text;v_seen text[]:=ARRAY[]::text[];
BEGIN
  IF p_genre IS NULL OR (p_section IS NOT NULL AND p_section NOT IN ('文学','哲学','評論','科学','その他')) THEN RETURN false;END IF;
  IF left(btrim(p_genre),1)='[' THEN v_values:=p_genre::jsonb;
  ELSIF btrim(p_genre)='' THEN v_values:='[]'::jsonb;
  ELSE v_values:=jsonb_build_array(p_genre);END IF;
  IF jsonb_typeof(v_values)<>'array' OR jsonb_array_length(v_values)>100 THEN RETURN false;END IF;
  FOR v_value IN SELECT value FROM jsonb_array_elements(v_values) LOOP
    IF jsonb_typeof(v_value)<>'string' THEN RETURN false;END IF;
    v_name:=v_value#>>'{}';
    IF v_name<>btrim(v_name) OR v_name=ANY(v_seen) OR NOT EXISTS(
      SELECT 1 FROM public.work_classifications c WHERE c.name=v_name AND (p_section IS NULL OR c.section=p_section)
    ) THEN RETURN false;END IF;
    v_seen:=array_append(v_seen,v_name);
  END LOOP;
  RETURN true;
EXCEPTION WHEN invalid_text_representation THEN RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION private.validate_revision_payload(p_data jsonb, p_refs jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_placeholder text;
BEGIN
  IF p_data IS NULL OR jsonb_typeof(p_data)<>'object' OR NOT private.valid_work_classifications(p_data->>'section',p_data->>'genre') THEN
    RAISE EXCEPTION '承認済みの小分類を選択してください（未選択も可能です）';
  END IF;
  v_placeholder:=CASE p_data->>'section' WHEN '哲学' THEN '理論哲学' WHEN '評論' THEN '文芸' WHEN '科学' THEN '数学' WHEN 'その他' THEN 'その他' ELSE '純文学' END;
  PERFORM private.validate_revision_payload_v781_base(jsonb_set(p_data,'{genre}',to_jsonb(v_placeholder)),p_refs);
END;
$function$

CREATE OR REPLACE FUNCTION private.validate_work_hierarchy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p_author uuid; chain_has_cycle boolean; chain_has_unpublished boolean; max_depth int;
begin
  -- Prevent two simultaneous parent changes by the same author from creating a cycle.
  perform pg_advisory_xact_lock(hashtext(new.author_id::text));
  if new.parent_work_id is null then return new; end if;
  if new.parent_work_id = new.id then raise exception '作品を自身の下に配置できません'; end if;
  select author_id into p_author from public.works where id=new.parent_work_id;
  if p_author is null or p_author <> new.author_id then
    raise exception '親作品には、自分が管理する作品だけを指定できます';
  end if;
  with recursive chain as (
    select id,parent_work_id,status,1 as depth from public.works where id=new.parent_work_id
    union all
    select w.id,w.parent_work_id,w.status,c.depth+1
    from public.works w join chain c on w.id=c.parent_work_id where c.depth<12
  ) select coalesce(bool_or(id=new.id),false),
           coalesce(bool_or(status not in ('published','open')),false),
           coalesce(max(depth),0)
    into chain_has_cycle,chain_has_unpublished,max_depth from chain;
  if chain_has_cycle then raise exception '親子関係が循環します'; end if;
  if max_depth>=12 then raise exception '階層は最大12段までです'; end if;
  if new.status in ('published','open') and chain_has_unpublished then
    raise exception '親作品を先に公開してください';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_work_v6(p_id uuid, p_pen_name text, p_title text, p_genre text, p_theme text, p_summary text, p_body text, p_question text, p_inheritance text, p_novelty text, p_status text, p_references jsonb, p_section text, p_contributor_credit text, p_parent_work_id uuid, p_order_index integer, p_node_kind text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
  if (select auth.uid()) is null then raise exception 'ログインしてください'; end if;
  if p_status not in ('draft','pending','open') then raise exception '投稿状態が不正です'; end if;
  if p_section is null or p_section not in ('文学','哲学','評論','科学','その他') then
    raise exception '分野が正しくありません';
  end if;
  if p_references is null or jsonb_typeof(p_references)<>'array'
     or jsonb_array_length(p_references)>20 then
    raise exception '参考文献は20件以内の配列にしてください';
  end if;
  if char_length(coalesce(p_contributor_credit,''))>120 then
    raise exception '入力／構成の名称は120文字以内にしてください';
  end if;
  if p_node_kind not in ('work','collection') or p_node_kind is null then
    raise exception '作品の種類が正しくありません';
  end if;
  if p_order_index is null or p_order_index not between 0 and 9999 then
    raise exception '並び順は0～9999の範囲で指定してください';
  end if;
  if p_id is null then
    insert into public.works(
      author_id,pen_name,contributor_credit,section,title,genre,theme,
      summary,body,question,inheritance,novelty,status,parent_work_id,order_index,node_kind)
    values ((select auth.uid()),p_pen_name,coalesce(p_contributor_credit,''),p_section,
      p_title,p_genre,p_theme,p_summary,p_body,p_question,p_inheritance,p_novelty,p_status,p_parent_work_id,p_order_index,p_node_kind)
    returning id into v_id;
  else
    update public.works set
      pen_name=p_pen_name,contributor_credit=coalesce(p_contributor_credit,''),section=p_section,
      title=p_title,genre=p_genre,theme=p_theme,summary=p_summary,body=p_body,
      parent_work_id=p_parent_work_id,order_index=p_order_index,node_kind=p_node_kind,
      question=p_question,inheritance=p_inheritance,novelty=p_novelty,status=p_status
    where id=p_id and author_id=(select auth.uid()) and status in ('draft','pending','rejected','open')
    returning id into v_id;
    if v_id is null then raise exception 'この作品は編集できません'; end if;
    delete from public.work_references where work_id=v_id;
  end if;
  insert into public.work_references(work_id,title,relation,url)
  select v_id,btrim(x->>'title'),coalesce(x->>'relation',''),nullif(btrim(x->>'url'),'')
  from jsonb_array_elements(p_references) as x;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.limit_work_reference_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(NEW.work_id::text));
  IF (SELECT count(*) FROM public.work_references WHERE work_id=NEW.work_id) >= 20 THEN
    RAISE EXCEPTION '参考文献は作品ごとに20件までです';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.review_revision(p_revision_id uuid, p_action text, p_review_note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_revision public.work_revisions%rowtype; v_work public.works%rowtype; v_next integer;
begin
  if not private.is_moderator() then raise exception '管理者のみ操作できます'; end if;
  if p_action not in ('approve','reject') then raise exception '不正な操作です'; end if;
  if char_length(coalesce(p_review_note,''))>1000 then raise exception '審査コメントが長すぎます'; end if;
  -- ロック順を統一するため work_id を取得して works -> revisions の順にロック。
  select work_id into v_revision.work_id from public.work_revisions where id=p_revision_id;
  if v_revision.work_id is null then raise exception '改訂案が見つかりません'; end if;
  select * into v_work from public.works where id=v_revision.work_id for update;
  select * into v_revision from public.work_revisions where id=p_revision_id for update;
  if v_revision.status<>'pending' then raise exception '審査待ちではありません'; end if;
  if p_action='reject' then
    update public.work_revisions set status='rejected',review_note=coalesce(p_review_note,''),
      reviewed_at=now(),updated_at=now() where id=p_revision_id;
    return;
  end if;
  if v_work.status<>'published' then raise exception '現在公開中の作品だけ承認できます'; end if;
  perform private.validate_revision_payload(v_revision.snapshot,v_revision.refs);
  v_next:=greatest(v_work.current_version,1)+1;
  update public.works set
    pen_name=v_revision.snapshot->>'pen_name',title=v_revision.snapshot->>'title',
    genre=v_revision.snapshot->>'genre',
    section=coalesce(v_revision.snapshot->>'section',v_work.section),
    contributor_credit=coalesce(v_revision.snapshot->>'contributor_credit',v_work.contributor_credit),
    theme=coalesce(v_revision.snapshot->>'theme',''),
    summary=v_revision.snapshot->>'summary',body=v_revision.snapshot->>'body',
    question=coalesce(v_revision.snapshot->>'question',''),
    inheritance=coalesce(v_revision.snapshot->>'inheritance',''),
    novelty=coalesce(v_revision.snapshot->>'novelty',''),current_version=v_next
  where id=v_work.id;
  delete from public.work_references where work_id=v_work.id;
  insert into public.work_references(work_id,title,relation,url)
  select v_work.id,btrim(x->>'title'),coalesce(x->>'relation',''),nullif(btrim(x->>'url'),'')
  from jsonb_array_elements(v_revision.refs) as x;
  update public.work_revisions set status='approved',version_number=v_next,
    review_note='',reviewed_at=now(),updated_at=now()
  where id=p_revision_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.protect_freely_published_works()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := (SELECT auth.uid());
  v_is_owner boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.freely_published_once := (NEW.status='open');
    RETURN NEW;
  END IF;

  v_is_owner := (v_actor IS NOT NULL AND OLD.author_id=v_actor);
  IF TG_OP = 'DELETE' THEN
    IF OLD.freely_published_once AND NOT v_is_owner THEN
      RAISE EXCEPTION '自由公開作品を管理者が直接削除することはできません';
    END IF;
    RETURN OLD;
  END IF;

  -- 設定値を任意の管理者更新で false に戻さない。
  NEW.freely_published_once := OLD.freely_published_once OR NEW.status='open';

  IF OLD.freely_published_once AND NEW.status IN ('published','pending','rejected') THEN
    RAISE EXCEPTION '自由公開した作品は審査済み・審査待ちへ変更できません。審査付き作品は新規作成してください';
  END IF;

  -- 審査済みの親グループを隠すことで、報告のない自由公開の下位本文まで
  -- 間接的に読めなくすることも防ぐ（投稿者本人の操作は除く）。
  IF NOT v_is_owner AND OLD.status IN ('published','open')
     AND (NEW.status NOT IN ('published','open')
          OR NEW.parent_work_id IS DISTINCT FROM OLD.parent_work_id) THEN
    IF EXISTS (
      WITH RECURSIVE children AS (
        SELECT id,parent_work_id,status,freely_published_once,1 AS depth
          FROM public.works WHERE parent_work_id=OLD.id
        UNION ALL
        SELECT w.id,w.parent_work_id,w.status,w.freely_published_once,c.depth+1
          FROM public.works w JOIN children c ON w.parent_work_id=c.id
         WHERE c.depth<12
      ) SELECT 1 FROM children WHERE freely_published_once AND status='open'
    ) AND NOT EXISTS (
      SELECT 1 FROM public.reports r WHERE r.work_id=OLD.id AND r.resolved=false
    ) THEN
      RAISE EXCEPTION '自由公開の下位作品を含むグループは、通報なしに非公開化・移動できません';
    END IF;
  END IF;

  -- 自由公開の掲載・本文は投稿者だけが変更できる。
  IF NOT v_is_owner AND (OLD.freely_published_once OR NEW.status='open') THEN
    IF OLD.status='open' AND NEW.status='hidden' THEN
      IF NOT private.is_moderator() OR NOT EXISTS (
        SELECT 1
          FROM private.reported_open_hide_authorizations a
          JOIN public.reports r ON r.id=a.report_id
         WHERE a.work_id=OLD.id AND a.moderator_id=v_actor
           AND r.work_id=OLD.id AND r.resolved=false
      ) THEN
        RAISE EXCEPTION '自由公開作品は未処理の通報に基づく専用操作でのみ非公開にできます';
      END IF;
      IF (to_jsonb(NEW) - 'status' - 'updated_at')
         IS DISTINCT FROM (to_jsonb(OLD) - 'status' - 'updated_at') THEN
        RAISE EXCEPTION '通報による非公開化では作品本文・所有者・その他の項目を変更できません';
      END IF;
      RETURN NEW;
    END IF;
    RAISE EXCEPTION '自由公開作品の掲載内容・公開状態を管理者が任意に変更することはできません';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private.protect_open_work_references()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_work_id uuid;
  v_owner_id uuid;
  v_freely_published boolean;
  v_status text;
BEGIN
  v_work_id := CASE WHEN TG_OP='DELETE' THEN OLD.work_id ELSE NEW.work_id END;
  SELECT author_id,freely_published_once,status
    INTO v_owner_id,v_freely_published,v_status FROM public.works WHERE id=v_work_id;
  IF v_freely_published AND v_status='open'
     AND v_owner_id IS DISTINCT FROM (SELECT auth.uid()) THEN
    RAISE EXCEPTION '自由公開作品の参考文献を管理者が直接編集することはできません';
  END IF;
  IF TG_OP='UPDATE' AND NEW.work_id IS DISTINCT FROM OLD.work_id THEN
    SELECT author_id,freely_published_once,status
      INTO v_owner_id,v_freely_published,v_status FROM public.works WHERE id=OLD.work_id;
    IF v_freely_published AND v_status='open'
       AND v_owner_id IS DISTINCT FROM (SELECT auth.uid()) THEN
      RAISE EXCEPTION '自由公開作品から参考文献を移動することはできません';
    END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$function$

CREATE OR REPLACE FUNCTION private.check_work_submission_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_event text;v_limit integer;v_count integer;
  v_now timestamptz:=statement_timestamp();v_start timestamptz;
  v_light boolean:=private.is_empty_work_group(NEW.node_kind,NEW.body);
BEGIN
  -- Groups with no text have one shared creation allowance, whether initially
  -- draft or public. Adding text later must acquire a body allowance.
  IF v_light THEN v_event:='group_created';v_limit:=100;
  ELSIF NEW.status='draft' THEN v_event:='draft_created';v_limit:=32;
  ELSIF TG_OP='INSERT' OR NEW.status IN ('pending','open','published') THEN v_event:='submitted';v_limit:=16;
  ELSE RETURN NEW;END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(NEW.author_id::text));
  IF EXISTS(SELECT 1 FROM private.work_daily_events WHERE work_id=NEW.id AND event_type=v_event) THEN RETURN NEW;END IF;
  -- Ordinary edits to previously submitted body works are never new creations.
  IF TG_OP='UPDATE' AND NOT v_light AND OLD.node_kind<>'collection' AND OLD.status=NEW.status
     AND EXISTS(SELECT 1 FROM private.work_daily_events WHERE work_id=NEW.id AND event_type IN ('draft_created','submitted')) THEN RETURN NEW;END IF;
  v_start:=private.work_quota_day_start(v_now);
  SELECT count(*) INTO v_count FROM private.work_daily_events
    WHERE author_id=NEW.author_id AND event_type=v_event AND event_at>=v_start AND event_at<v_start+interval '24 hours';
  IF v_count>=v_limit THEN
    IF v_event='group_created' THEN RAISE EXCEPTION '本文なしグループは1日100件までです。毎日0:00（日本時間）に更新します。';
    ELSIF v_event='draft_created' THEN RAISE EXCEPTION '新規下書きは1日32件までです。毎日0:00（日本時間）に更新します。';
    ELSE RAISE EXCEPTION '本文の新規投稿は1日16件までです。毎日0:00（日本時間）に更新します。';END IF;
  END IF;
  INSERT INTO private.work_daily_events(work_id,author_id,event_type,event_at) VALUES(NEW.id,NEW.author_id,v_event,v_now);
  RETURN NEW;
END;
$function$
